344	<body>
345	  <main>
346	    <button type="button" class="circle-container" id="decorative-circle" aria-label="Interactive circle - press Space to toggle, double-click to change color" aria-pressed="false">
347	      <svg viewBox="0 0 400 400" aria-hidden="true" role="presentation">
348	        <circle cx="200" cy="200" r="200"/>
349	      </svg>
350	    </button>
351	    <div class="mode-indicator" id="mode-indicator" aria-live="polite" aria-atomic="true"></div>
352	    <div class="hint" id="hint-text" role="status" aria-live="polite" aria-relevant="text">Click to activate • Double-click to change color</div>
353	    <div class="controls" role="group" aria-label="Circle controls">
354	      <button type="button" class="control-btn" id="cycle-btn" aria-label="Cycle to next color">Cycle Color</button>
355	      <button type="button" class="control-btn" id="reset-btn" aria-label="Reset to default state">Reset</button>
356	    </div>
357	    <div class="keyboard-hint" aria-label="Keyboard shortcuts">Press <kbd>C</kbd> to cycle • <kbd>R</kbd> to reset</div>
358	  </main>
359	
360	  <script>
361	    const CONFIG = {
362	      storageKey: 'circle-state',
363	      tapDelay: 300,
364	      colorShiftDuration: 500,
365	      colorModes: [
366	        { class: 'default', name: 'Default White' },
367	        { class: 'color-mode-1', name: 'Pink' },
368	        { class: 'color-mode-2', name: 'Teal' },
369	        { class: 'color-mode-3', name: 'Mint' }
370	      ],
371	      isTouch: 'ontouchstart' in window || navigator.maxTouchPoints > 0,
372	      pulseInterval: 2500
373	    };
374	
375	    const el = {
376	      circle: document.getElementById('decorative-circle'),
377	      hint: document.getElementById('hint-text'),
378	      modeIndicator: document.getElementById('mode-indicator'),
379	      cycleBtn: document.getElementById('cycle-btn'),
380	      resetBtn: document.getElementById('reset-btn')
381	    };
382	
383	    let state = { active: false, colorMode: 0 };
384	    let tapCount = 0;
385	    let tapTimeout = null;
386	    let animatingColorShift = false;
387	
388	    const getColorModeClass = (mode) => CONFIG.colorModes[mode % CONFIG.colorModes.length].class;
389	    const getColorModeName = (mode) => CONFIG.colorModes[mode % CONFIG.colorModes.length].name;
390	
391	    const storage = {
392	      save() {
393	        try {
394	          localStorage.setItem(CONFIG.storageKey, JSON.stringify(state));
395	        } catch {
396	          // Silently fail if localStorage is unavailable or quota exceeded
397	        }
398	      },
399	      load() {
400	        try {
401	          const saved = localStorage.getItem(CONFIG.storageKey);
402	          if (saved) {
403	            const parsed = JSON.parse(saved);
404	            if (parsed && typeof parsed === 'object') {
405	              state = { ...state, ...parsed };
406	            }
407	          }
408	        } catch {
409	          // Silently fail if parsing fails
410	        }
411	      }
412	    };
413	
414	    const updateClasses = () => {
415	      const colorClasses = CONFIG.colorModes.map(m => m.class);
416	      el.circle.classList.remove('active', ...colorClasses);
417	      el.circle.setAttribute('aria-pressed', state.active);
418	      if (state.active) el.circle.classList.add('active');
419	      if (state.colorMode > 0) el.circle.classList.add(getColorModeClass(state.colorMode));
420	    };
421	
422	    const updateUI = () => {
423	      const mainText = state.active ? 'Active!' : 'Click to activate';
424	      let hintParts = [mainText];
425	
426	      if (CONFIG.isTouch) {
427	        hintParts.push(state.active ? 'Tap to change color' : 'Tap twice to change color');
428	      } else {
429	        hintParts.push('Double-click to change color');
430	      }
431	
432	      el.hint.textContent = hintParts.join(' • ');
433	
434	      const showMode = state.active && state.colorMode > 0;
435	      el.modeIndicator.classList.toggle('visible', showMode);
436	      if (showMode) {
437	        const modeName = getColorModeName(state.colorMode);
438	        el.modeIndicator.textContent = modeName;
439	      }
440	    };
441	
442	    const applyState = () => {
443	      updateClasses();
444	      updateUI();
445	    };
446	
447	    const toggleActive = () => {
448	      state.active = !state.active;
449	      applyState();
450	      storage.save();
451	    };
452	
453	    const cycleColor = () => {
454	      if (animatingColorShift) return;
455	      animatingColorShift = true;
456	      state.colorMode = (state.colorMode + 1) % CONFIG.colorModes.length;
457	      state.active = true;
458	      el.circle.classList.add('color-shifting');
459	      setTimeout(() => {
460	        el.circle.classList.remove('color-shifting');
461	        animatingColorShift = false;
462	      }, CONFIG.colorShiftDuration);
463	      applyState();
464	      storage.save();
465	    };
466	
467	    const resetState = () => {
468	      state = { active: false, colorMode: 0 };
469	      applyState();
470	      storage.save();
471	    };
472	
473	    const handleDblClick = (e) => {
474	      e.preventDefault();
475	      cycleColor();
476	    };
477	
478	    const handleTouchEnd = () => {
479	      tapCount++;
480	      clearTimeout(tapTimeout);
481	      if (tapCount === 1) {
482	        tapTimeout = setTimeout(() => {
483	          if (tapCount === 1) toggleActive();
484	          tapCount = 0;
485	        }, CONFIG.tapDelay);
486	      } else if (tapCount === 2) {
487	        cycleColor();
488	        tapCount = 0;
489	      }
490	    };
491	
492	    const keyHandlers = {
493	      ' ': toggleActive,
494	      'enter': toggleActive,
495	      'c': cycleColor,
496	      'r': resetState
497	    };
498	
499	    const handleKeyDown = (e) => {
500	      const handler = keyHandlers[e.key.toLowerCase()];
501	      if (handler) {
502	        e.preventDefault();
503	        handler();
504	      }
505	    };
506	
507	    const initListeners = () => {
508	      el.circle.addEventListener('click', toggleActive);
509	      el.circle.addEventListener('dblclick', handleDblClick);
510	      el.circle.addEventListener('touchend', handleTouchEnd);
511	      el.circle.addEventListener('blur', () => {
512	        tapCount = 0;
513	        clearTimeout(tapTimeout);
514	      });
515	      document.addEventListener('keydown', handleKeyDown);
516	      el.cycleBtn.addEventListener('click', cycleColor);
517	      el.resetBtn.addEventListener('click', resetState);
518	    };
519	
520	    const initApp = () => {
521	      storage.load();
522	      applyState();
523	      initListeners();
524	      requestAnimationFrame(() => el.circle.focus());
525	    };
526	
527	    if (document.readyState === 'loading') {
528	      document.addEventListener('DOMContentLoaded', initApp);
529	    } else {
530	      initApp();
531	    }
532	  </script>
533	</body>
534	</html>
